use verus::prelude::*;

/// Appends `values` onto the end of `arr`, returning the concatenation.
/// 
/// # Specification
/// - Ensures the resulting vector’s length is the sum of the input lengths.
/// - Ensures the prefix up to `arr.len()` is exactly `arr`.
/// - Ensures the suffix of length `values.len()` is exactly `values`.
#[requires(true)]
#[ensures(
    result.len() == old(arr).len() + old(values).len()
)]
#[ensures(
    forall |i: usize| i < old(arr).len() ==> result[i] == old(arr)[i]
)]
#[ensures(
    forall |j: usize| j < old(values).len() ==>
        result[old(arr).len() + j] == old(values)[j]
)]
fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    let mut result = arr;
    // Pre-allocate enough space for the combined vector
    result.reserve(values.len());
    // Append all elements from `values` into `result`
    result.extend(values);
    result
}